UPDATE public."teammates" SET
		"user_id" = '{{update_form.fieldState.user_id.isVisible ? update_form.formData.user_id : update_form.sourceData.user_id}}',
		"user_name" = '{{update_form.fieldState.user_name.isVisible ? update_form.formData.user_name : update_form.sourceData.user_name}}'
WHERE "user_id" = '{{data_table.selectedRow.user_id}}'
AND {{
  ["p.solovev@sdgroup.ai"].map((e) => e.toLowerCase()).includes((appsmith.user.email || "").toLowerCase())
    ? "TRUE"
    : "FALSE"
}};
